/*
 * Artwork inner-page content — one record per Figma "פריט קצה" detail frame.
 *
 * All 22 detail frames share one layout, so rather than 22 near-identical HTML
 * files this is data + a single template (artwork.html?id=<id>). Collection
 * pages link their cards here by id.
 *
 * Geometry fields are the Figma frame's own px values at the 1728px width; the
 * template scales them. They vary per frame because each artwork's render has a
 * different aspect and each blurb a different length, so they are data rather
 * than constants:
 *   imgW/imgH/imgTop  the centred artwork render
 *   bodyTop           top of the left-hand blurb column
 *   bodyRight         the blurb column's RIGHT edge (it is right-aligned, RTL)
 *   bodyWidth         blurb column width
 *   metaTop           top of the right-hand metadata table
 *   dimsTop           the "(גובה ...)" line; the tags line sits 34px below it
 *
 * body: array of paragraphs; each paragraph is an array of segments.
 *       { t } renders plain, { t, u: true } renders underlined — the design's
 *       in-copy links back into the filter/motif vocabulary.
 * meta: the right-hand table rows, top to bottom, separated by hairline rules.
 * tags: the "מעגל / אדום / אבן" line under the dimensions.
 * motif: which word in the top motif row renders as the current one.
 */
