// cardId -> inner-page href, for the collection grids. A record's own id is
// already the card id on the אנכיות and שער grids; the מעגל grid predates these
// pages and names the same works differently, so those records carry `cards`.
window.ARTWORK_HREF = window.ARTWORKS.reduce(function (map, art) {
  (art.cards || [art.id]).forEach(function (cardId) {
    map[cardId] = "artwork.html?id=" + art.id;
  });
  return map;
}, {});
